describe('Change Billing Address During Checkout', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="checkout-page"]').should('be.visible');
  });

  it('should successfully change billing address during checkout', () => {
    // Navigate to billing address section
    cy.get('[data-testid="billing-section"]').click();
    cy.get('[data-testid="change-address-btn"]').should('be.visible').click();

    // Verify address form is displayed
    cy.get('[data-testid="address-form"]').should('be.visible');

    // Fill in new billing address
    cy.get('[data-testid="address-street-input"]').clear().type('123 New Street');
    cy.get('[data-testid="address-city-input"]').clear().type('New York');
    cy.get('[data-testid="address-state-select"]').select('NY');
    cy.get('[data-testid="address-zip-input"]').clear().type('10001');
    cy.get('[data-testid="address-country-select"]').select('United States');

    // Submit the address change
    cy.get('[data-testid="save-address-btn"]').click();

    // Verify success message
    cy.get('[data-testid="success-message"]').should('contain', 'Address updated successfully');

    // Verify the address is updated in the checkout summary
    cy.get('[data-testid="billing-address-display"]').should('contain', '123 New Street');
    cy.get('[data-testid="billing-address-display"]').should('contain', 'New York, NY 10001');

    // Verify user can proceed to payment
    cy.get('[data-testid="proceed-to-payment-btn"]').should('be.enabled');
  });

  it('should display validation errors for incomplete billing address', () => {
    // Navigate to billing address section
    cy.get('[data-testid="billing-section"]').click();
    cy.get('[data-testid="change-address-btn"]').click();

    // Verify address form is displayed
    cy.get('[data-testid="address-form"]').should('be.visible');

    // Fill in only partial address information
    cy.get('[data-testid="address-street-input"]').type('456 Incomplete Ave');
    cy.get('[data-testid="address-city-input"]').type('Boston');
    // Intentionally skip state and zip

    // Attempt to submit incomplete form
    cy.get('[data-testid="save-address-btn"]').click();

    // Verify validation error messages appear
    cy.get('[data-testid="address-state-error"]').should('be.visible').and('contain', 'State is required');
    cy.get('[data-testid="address-zip-error"]').should('be.visible').and('contain', 'ZIP code is required');

    // Verify save button remains disabled
    cy.get('[data-testid="save-address-btn"]').should('be.disabled');

    // Verify address was not updated
    cy.get('[data-testid="success-message"]').should('not.exist');
  });

  it('should allow user to cancel address change and return to checkout', () => {
    // Navigate to billing address section
    cy.get('[data-testid="billing-section"]').click();
    cy.get('[data-testid="change-address-btn"]').click();

    // Verify address form is displayed
    cy.get('[data-testid="address-form"]').should('be.visible');

    // Start filling in address
    cy.get('[data-testid="address-street-input"]').type('789 Cancel Street');

    // Click cancel button
    cy.get('[data-testid="cancel-address-btn"]').click();

    // Verify form is closed
    cy.get('[data-testid="address-form"]').should('not.be.visible');

    // Verify original address is still displayed
    cy.get('[data-testid="billing-address-display"]').should('exist');
    cy.get('[data-testid="billing-address-display"]').should('not.contain', '789 Cancel Street');
  });

  it('should handle special characters and international addresses', () => {
    // Navigate to billing address section
    cy.get('[data-testid="billing-section"]').click();
    cy.get('[data-testid="change-address-btn"]').click();

    // Fill in address with special characters
    cy.get('[data-testid="address-street-input"]').clear().type("123 O'Connor St. #456");
    cy.get('[data-testid="address-city-input"]').clear().type('São Paulo');
    cy.get('[data-testid="address-country-select"]').select('Brazil');
    cy.get('[data-testid="address-state-input"]').clear().type('SP');
    cy.get('[data-testid="address-zip-input"]').clear().type('01310-100');

    // Submit the address change
    cy.get('[data-testid="save-address-btn"]').click();

    // Verify success message
    cy.get('[data-testid="success-message"]').should('contain', 'Address updated successfully');

    // Verify special characters are preserved
    cy.get('[data-testid="billing-address-display"]').should('contain', "O'Connor");
    cy.get('[data-testid="billing-address-display"]').should('contain', 'São Paulo');
  });
});
